helpers.log('Starting HTTP Headers node execution');

const headers = node.properties.headers.value || [];
const includeDefaults = node.properties.includeDefaults.value;

helpers.log(`Processing ${headers.length} custom header(s)`);
helpers.log(`Include defaults: ${includeDefaults}`);

const outputHeaders = {};

// Add default headers if enabled
if (includeDefaults) {
  outputHeaders['User-Agent'] = 'Nodify/1.0';
  outputHeaders['Accept'] = '*/*';
  helpers.log('Added default headers');
}

// Process custom headers
for (const header of headers) {
  if (!header.enabled) {
    helpers.log(`Skipping disabled header: ${header.key}`);
    continue;
  }

  if (!header.key || !header.value) {
    helpers.warn('Skipping header with missing key or value');
    continue;
  }

  const key = String(header.key).trim();
  const value = String(header.value).trim();

  outputHeaders[key] = value;
  helpers.log(`Set header: ${key} = ${value}`);
}

helpers.log(`Total headers configured: ${Object.keys(outputHeaders).length}`);

return {
  ...data,
  headers: outputHeaders,
  headerCount: Object.keys(outputHeaders).length
};
